// ==============================================
// DRONE SIMULATOR
// Frontend-only Drone Flight Simulator
// ==============================================

export type DroneStatus =
  | "ground"
  | "taking_off"
  | "flying"
  | "reached"
  | "returning";

export interface DroneState {
  droneId: string;

  latitude: number;
  longitude: number;
  altitude: number;

  homeLatitude: number;
  homeLongitude: number;

  targetLatitude?: number;
  targetLongitude?: number;

  status: DroneStatus;

  battery: number;
  speed: number;
  heading: number;

  mode: "STABILIZE" | "AUTO" | "RTL";

  targetReached: boolean;
}

export interface SendDroneOptions {
  droneId: string;
  targetLatitude: number;
  targetLongitude: number;
}

type EventHandler = (payload: any) => void;

class DroneSimulator {
  private drones = new Map<string, DroneState>();

  private listeners = new Map<string, EventHandler[]>();

  private timer: NodeJS.Timeout | null = null;

  constructor() {
    this.startLoop();
  }

  // ============================================
  // EVENT BUS
  // ============================================

  on(event: string, callback: EventHandler) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }

    this.listeners.get(event)!.push(callback);
  }

  off(event: string, callback: EventHandler) {
    const arr = this.listeners.get(event);

    if (!arr) return;

    this.listeners.set(
      event,
      arr.filter((x) => x !== callback)
    );
  }

  private emit(event: string, payload: any) {
    const arr = this.listeners.get(event);

    if (!arr) return;

    arr.forEach((cb) => cb(payload));
  }

  // ============================================
  // REGISTER DRONE
  // ============================================

  registerDrone(data: {
    droneId: string;
    latitude: number;
    longitude: number;
  }) {
    if (this.drones.has(data.droneId)) return;

    this.drones.set(data.droneId, {
      droneId: data.droneId,

      latitude: data.latitude,
      longitude: data.longitude,

      homeLatitude: data.latitude,
      homeLongitude: data.longitude,

      altitude: 0,

      battery: 100,

      speed: 0,

      heading: 0,

      status: "ground",

      mode: "STABILIZE",

      targetReached: false,
    });
  }

  getDrone(droneId: string) {
    return this.drones.get(droneId);
  }

  getAllDrones() {
    return [...this.drones.values()];
  }

  // ============================================
  // SEND DRONE
  // ============================================

  sendDrone(data: SendDroneOptions) {
    const drone = this.drones.get(data.droneId);


    if (!drone) return;
    console.log("SEND DRONE", data);
    if (drone.status === "flying") return;

    drone.targetLatitude = data.targetLatitude;
    drone.targetLongitude = data.targetLongitude;

    drone.status = "taking_off";
    drone.mode = "AUTO";
    drone.targetReached = false;

    this.emit("mission_started", {
      droneId: drone.droneId,
      targetLat: data.targetLatitude,
      targetLng: data.targetLongitude,
    });
  }

  // ============================================
  // RETURN HOME
  // ============================================

  recallDrone(droneId: string) {
    const drone = this.drones.get(droneId);

    if (!drone) return;

    drone.targetLatitude = drone.homeLatitude;
    drone.targetLongitude = drone.homeLongitude;

    drone.status = "returning";
    drone.mode = "RTL";
  }

  // ============================================
  // PATROL
  // ============================================

  patrolDrone(droneId: string) {
    const drone = this.drones.get(droneId);

    if (!drone) return;

    const offset = 0.001;

    drone.targetLatitude = drone.homeLatitude + offset;
    drone.targetLongitude = drone.homeLongitude + offset;

    drone.status = "taking_off";
    drone.mode = "AUTO";
  }

  // ============================================
  // MAIN LOOP
  // ============================================

  private startLoop() {
    if (this.timer) return;

    this.timer = setInterval(() => {
      this.update();
    }, 100);
  }

  private update() {
    this.drones.forEach((drone) => {
      this.updateDrone(drone);
    });
  }
  // ============================================
// REGISTER MULTIPLE DRONES
// ============================================

registerFleet(
  drones: {
    droneId: string;
    latitude: number | null;
    longitude: number | null;
  }[]
) {
  console.log("Registering fleet:", drones);
  drones.forEach((drone) => {
    if (
      drone.latitude == null ||
      drone.longitude == null
    ) {
      return;
    }

    this.registerDrone({
      droneId: drone.droneId,
      latitude: drone.latitude,
      longitude: drone.longitude,
    });
  });
   console.log("Simulator drones:", this.getAllDrones());
}

  // implemented in Part 2
 
private updateDrone(drone: DroneState) {
    
  if (!drone.targetLatitude || !drone.targetLongitude) return;

  // -----------------------------
  // Takeoff
  // -----------------------------
  if (drone.status === "taking_off") {
    drone.altitude += 2;

    if (drone.altitude >= 40) {
      drone.altitude = 40;
      drone.status = "flying";
    }

    this.emitTelemetry(drone);
    return;
  }

  // -----------------------------
  // Flying / Returning
  // -----------------------------
  if (
    drone.status === "flying" ||
    drone.status === "returning"
  ) {
    const distance = this.distanceMeters(
      drone.latitude,
      drone.longitude,
      drone.targetLatitude,
      drone.targetLongitude
    );

    if (distance < 3) {
      // reached target

      if (drone.mode === "RTL") {
        drone.altitude = 0;
        drone.speed = 0;
        drone.status = "ground";
        drone.mode = "STABILIZE";
      } else {
        drone.status = "reached";
        drone.speed = 0;
        drone.targetReached = true;
      }

      this.emit("mission_completed", {
        droneId: drone.droneId,
      });

      this.emitTelemetry(drone);
      return;
    }

    // Move drone

    drone.latitude = this.moveTowards(
      drone.latitude,
      drone.targetLatitude,
      0.02
    );

    drone.longitude = this.moveTowards(
      drone.longitude,
      drone.targetLongitude,
      0.02
    );

    drone.speed = 10 + Math.random() * 4;

    drone.heading = this.calculateHeading(
      drone.latitude,
      drone.longitude,
      drone.targetLatitude,
      drone.targetLongitude
    );

    drone.battery = Math.max(
      5,
      drone.battery - 0.02
    );

    this.emitPosition(drone);
    this.emitTelemetry(drone);

    return;
  }

  // -----------------------------
  // Reached target
  // -----------------------------
  if (drone.status === "reached") {
    drone.battery = Math.max(
      5,
      drone.battery - 0.005
    );

    this.emitTelemetry(drone);
  }
}

// ============================================
// HELPERS
// ============================================

private moveTowards(
  current: number,
  target: number,
  factor: number
) {
  return current + (target - current) * factor;
}


private distanceMeters(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
) {
  const R = 6371000;

  const dLat =
    ((lat2 - lat1) * Math.PI) / 180;

  const dLon =
    ((lon2 - lon1) * Math.PI) / 180;

  const a =
    Math.sin(dLat / 2) *
      Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);

  return (
    R *
    2 *
    Math.atan2(
      Math.sqrt(a),
      Math.sqrt(1 - a)
    )
  );
}



private calculateHeading(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
) {
  const dLon = lon2 - lon1;
  const dLat = lat2 - lat1;

  const angle =
    (Math.atan2(dLon, dLat) * 180) /
    Math.PI;

  return (angle + 360) % 360;
}
// ============================================
// POSITION EVENT
// ============================================

private emitPosition(drone: DroneState) {
 this.emit("drone_position", {
    id: drone.droneId,
    droneId: drone.droneId,

    lat: drone.latitude,
    lng: drone.longitude,
    alt: drone.altitude,

    ts: Date.now(),
});
}

// ============================================
// TELEMETRY EVENT
// ============================================

private emitTelemetry(drone: DroneState) {
  this.emit("drone_telemetry", {
  droneDbId: drone.droneId,
  droneId: drone.droneId,

  lat: drone.latitude,
  lng: drone.longitude,
  alt: drone.altitude,

  battery: Number(drone.battery.toFixed(1)),
  speed: Number(drone.speed.toFixed(1)),
  heading: Math.round(drone.heading),

  mode: drone.mode,

  status:
    drone.status === "ground"
      ? "ground"
      : drone.status === "reached"
      ? "reached"
      : "on_air",

  targetLat: drone.targetLatitude ?? null,
  targetLng: drone.targetLongitude ?? null,

  targetDistance: null,

  satellites: 12,
  gpsFix: "3D",
  windSpeed: 3,

  command: null,

  ts: Date.now(),
});
}
// ============================================
// PUBLIC EVENT API
// ============================================

public subscribe(
  event: string,
  callback: EventHandler
) {
  this.on(event, callback);
}

public unsubscribe(
  event: string,
  callback: EventHandler
) {
  this.off(event, callback);
}
}


export const droneSimulator = new DroneSimulator();

