// Mock Drone Command API

export interface SendDronePayload {
  droneDbId: string;
  targetLatitude: number;
  targetLongitude: number;
  sensorId?: string;
  alertId?: string;
}

export interface SimpleDroneCommandPayload {
  droneDbId: string;
}

export interface DroneCommandResponse {
  success: boolean;
  message?: string;
  flightId?: any;
  error?: string;
}

const delay = (ms = 500) =>
  new Promise((resolve) => setTimeout(resolve, ms));

import { droneSimulator } from "@/lib/simulator/simulator";

export async function sendDrone(
  payload: SendDronePayload
): Promise<DroneCommandResponse> {

  await new Promise((r) => setTimeout(r, 400));

  const drone = droneSimulator
    .getAllDrones()
    .find((d) => d.droneId === payload.droneDbId);

  if (!drone) {
    return {
      success: false,
      error: "Drone not found",
    };
  }

  droneSimulator.sendDrone({
    droneId: payload.droneDbId,
    targetLatitude: payload.targetLatitude,
    targetLongitude: payload.targetLongitude,
  });

  return {
    success: true,
    message: "Drone dispatched",
  };
}

export async function dropPayload(
  payload: SimpleDroneCommandPayload
): Promise<DroneCommandResponse> {
  await delay();

  console.log("📦 DROP PAYLOAD", payload);

  return {
    success: true,
    message: "Payload dropped successfully",
  };
}

export async function recallDrone(
  payload: SimpleDroneCommandPayload
): Promise<DroneCommandResponse> {

  await new Promise((r) => setTimeout(r, 300));

  droneSimulator.recallDrone(payload.droneDbId);

  return {
    success: true,
    message: "Drone recalled",
  };
}

export async function dronePatrol(
  payload: SimpleDroneCommandPayload
): Promise<DroneCommandResponse> {

  await new Promise((r) => setTimeout(r, 300));

  droneSimulator.patrolDrone(payload.droneDbId);

  return {
    success: true,
    message: "Patrol started",
  };
}