// lib/api/rtsp.ts]

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

export interface RtspOpenResult {
  pid?: number; // process id on server (if server provides)
  sensorDbId?: string; // sensor id that was launched (if server provides)
}

/**
 * internal helper to fetch with timeout and safe json parsing
 */
const delay = (ms = 500) =>
  new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Ask backend to open the RTSP stream of a sensor in VLC (or configured player)
 * Body: { sensorDbId: string }  // DB id of sensor
 *
 * Returns ApiResponse<RtspOpenResult>
 */

export async function openRtspBySensor(
  sensorDbId: string,
  timeoutMs = 10000,
): Promise<ApiResponse<RtspOpenResult>> {
  await delay();

  if (!sensorDbId) {
    return {
      success: false,
      error: "sensorDbId is required",
    };
  }

  console.log("[MOCK] Opening RTSP for sensor:", sensorDbId);

  return {
    success: true,
    data: {
      pid: Math.floor(Math.random() * 10000),
      sensorDbId,
    },
    message: "RTSP stream opened successfully (Demo)",
  };
}


export async function openRtsp(
  params: { sensorDbId?: string; rtspUrl?: string },
  timeoutMs = 10000,
): Promise<ApiResponse<RtspOpenResult>> {
  await delay();

  if (!params.sensorDbId && !params.rtspUrl) {
    return {
      success: false,
      error: "sensorDbId or rtspUrl is required",
    };
  }

  console.log("[MOCK] Opening RTSP:", params);

  return {
    success: true,
    data: {
      pid: Math.floor(Math.random() * 10000),
      sensorDbId: params.sensorDbId,
    },
    message: "RTSP stream opened successfully (Demo)",
  };
}
/**
 * stopRtsp(payload: { sensorDbId?: string; pid?: number })
 * Calls server endpoint to stop a previously launched player.
 * Keep this in case you re-enable stop from the UI.
 */

export async function stopRtsp(payload: {
  sensorDbId?: string;
  pid?: number;
}): Promise<ApiResponse> {
  await delay();

  if (!payload.sensorDbId && !payload.pid) {
    return {
      success: false,
      error: "Provide sensorDbId or pid",
    };
  }

  console.log("[MOCK] Stopping RTSP:", payload);

  return {
    success: true,
    message: "RTSP stream stopped successfully (Demo)",
  };
}