export interface DroneOS {
  id: string;
  droneId: string;
  droneOSName: string;
  droneType: string;
  videoLink?: string | null;
  gpsFix: string;
  minHDOP: number;
  minSatCount: number;
  maxWindSpeed: number;
  droneSpeed: number;
  targetAltitude: number;
  gpsLost: string;
  telemetryLost: string;
  minBatteryLevel: number;
  usbAddress: string;
  batteryFailSafe: string;
  gpsName: string;
  maxAltitude: number;
  latitude?: number | null;
  longitude?: number | null;
  addedBy: string;
  areaId?: string | null;
  area?: {
    id: string;
    areaId: string;
    name: string;
    latitude: number;
    longitude: number;
    status: string;
  };
  createdAt: string;
  updatedAt: string;
}

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  count?: number;
  error?: string;
  message?: string;
}

export interface PaginationMeta {
  page: number;
  limit: number;
  totalCount: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

export interface PaginatedApiResponse<T> {
  success: boolean;
  data?: T;
  pagination?: PaginationMeta;
  error?: string;
  message?: string;
}

