export async function getAllDroneOS(params?: {
  areaId?: string;
  include?: boolean;
  page?: number;
  limit?: number;
  search?: string;
}): Promise<PaginatedApiResponse<DroneOS[]>> {
  await new Promise((r) => setTimeout(r, 300));

  let data = [...mockDrones];

  if (params?.areaId) {
    data = data.filter((d) => d.areaId === params.areaId);
  }

  if (params?.search) {
    const search = params.search.toLowerCase();

    data = data.filter(
      (d) =>
        d.droneId.toLowerCase().includes(search) ||
        d.droneOSName.toLowerCase().includes(search) ||
        d.droneType.toLowerCase().includes(search) ||
        d.gpsName.toLowerCase().includes(search)
    );
  }

  return {
    success: true,
    data,
    pagination: {
      page: 1,
      limit: data.length,
      totalCount: data.length,
      totalPages: 1,
      hasNextPage: false,
      hasPrevPage: false,
    },
  };
}

export async function getDroneStats(): Promise<
  ApiResponse<{
    total: number;
    assigned: number;
    unassigned: number;
  }>
> {
  await new Promise((r) => setTimeout(r, 200));

  return {
    success: true,
    data: {
      total: mockDrones.length,
      assigned: mockDrones.filter((d) => d.areaId !== null).length,
      unassigned: mockDrones.filter((d) => d.areaId === null).length,
    },
  };
}

export async function getDroneOSById(
  id: string,
  includeArea = false,
): Promise<ApiResponse<DroneOS>> {
  await new Promise((r) => setTimeout(r, 300));

  const drone = mockDrones.find((d) => d.id === id);

  if (!drone) {
    return {
      success: false,
      error: "Drone not found",
    };
  }

  return {
    success: true,
    data: drone,
  };
}

export async function getDronesByArea(
  areaId: string,
  includeArea = false,
): Promise<ApiResponse<DroneOS[]>> {
  await new Promise((r) => setTimeout(r, 300));

  const drones = mockDrones.filter((d) => d.areaId === areaId);

  return {
    success: true,
    count: drones.length,
    data: drones,
  };
}

export async function createDroneOS(droneData: {
  droneId: string;
  droneOSName: string;
  droneType: string;
  videoLink?: string;
  gpsFix: string;
  minHDOP: number;
  minSatCount: number;
  maxWindSpeed: number;
  droneSpeed: number;
  targetAltitude: number;
  gpsLost: string;
  telemetryLost: string;
  minBatteryLevel: number;
  usbAddress: string;
  batteryFailSafe: string;
  gpsName: string;
  maxAltitude: number;
  latitude: number;
  longitude: number;
  addedBy: string;
  areaId?: string;
}): Promise<ApiResponse<DroneOS>> {
  await new Promise((r) => setTimeout(r, 300));

  const newDrone: DroneOS = {
    id: `drone-${mockDrones.length + 1}`,
    ...droneData,
    videoLink: droneData.videoLink || null,
    areaId: droneData.areaId || null,
    area:
      droneData.areaId === "area-1"
        ? {
            id: "area-1",
            areaId: "AREA-001",
            name: "North Zone",
            latitude: 28.6139,
            longitude: 77.209,
            status: "Active",
          }
        : droneData.areaId === "area-2"
        ? {
            id: "area-2",
            areaId: "AREA-002",
            name: "South Zone",
            latitude: 28.5355,
            longitude: 77.391,
            status: "Active",
          }
        : droneData.areaId === "area-3"
        ? {
            id: "area-3",
            areaId: "AREA-003",
            name: "East Zone",
            latitude: 28.7041,
            longitude: 77.1025,
            status: "Inactive",
          }
        : undefined,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  mockDrones.unshift(newDrone);

  return {
    success: true,
    data: newDrone,
    message: "Drone created successfully",
  };
}

export async function updateDroneOS(
  id: string,
  droneData: Partial<{
    droneId: string;
    droneOSName: string;
    droneType: string;
    videoLink: string | null;
    gpsFix: string;
    minHDOP: number;
    minSatCount: number;
    maxWindSpeed: number;
    droneSpeed: number;
    targetAltitude: number;
    gpsLost: string;
    telemetryLost: string;
    minBatteryLevel: number;
    usbAddress: string;
    batteryFailSafe: string;
    gpsName: string;
    maxAltitude: number;
    latitude: number | null;
    longitude: number | null;
    areaId: string | null;
  }>,
): Promise<ApiResponse<DroneOS>> {
  await new Promise((r) => setTimeout(r, 300));

  const drone = mockDrones.find((d) => d.id === id);

  if (!drone) {
    return {
      success: false,
      error: "Drone not found",
    };
  }

  Object.assign(drone, droneData);

  if (droneData.areaId !== undefined) {
    if (droneData.areaId === "area-1") {
      drone.area = {
        id: "area-1",
        areaId: "AREA-001",
        name: "North Zone",
        latitude: 28.6139,
        longitude: 77.209,
        status: "Active",
      };
    } else if (droneData.areaId === "area-2") {
      drone.area = {
        id: "area-2",
        areaId: "AREA-002",
        name: "South Zone",
        latitude: 28.5355,
        longitude: 77.391,
        status: "Active",
      };
    } else if (droneData.areaId === "area-3") {
      drone.area = {
        id: "area-3",
        areaId: "AREA-003",
        name: "East Zone",
        latitude: 28.7041,
        longitude: 77.1025,
        status: "Inactive",
      };
    } else {
      drone.area = undefined;
    }
  }

  drone.updatedAt = new Date().toISOString();

  return {
    success: true,
    data: drone,
    message: "Drone updated successfully",
  };
}

export async function deleteDroneOS(
  id: string,
): Promise<ApiResponse<null>> {
  await new Promise((r) => setTimeout(r, 300));

  const index = mockDrones.findIndex((d) => d.id === id);

  if (index !== -1) {
    mockDrones.splice(index, 1);
  }

  return {
    success: true,
    message: "Drone deleted successfully",
  };
}