export type AlertStatus = "ACTIVE" | "SENT" | "NEUTRALISED";

export interface Alert {
  id: string;
  sensorDbId: string;
  sensorId: string;
  type: string;
  message: string;
  status: AlertStatus;
  createdAt: string;
  decidedAt: string | null;
  decision: string | null;
  time: string | null;
  metadata?: any;

  sensor?: {
    id: string;
    sensorId: string;
    name: string;
    latitude: number;
    longitude: number;
    rtspUrl?: string;

    area?: {
      id: string;
      areaId: string;
      name: string;
    };
  };
}

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  count?: number;
  error?: string;
  message?: string;
  skipped?: boolean;
  pagination?: {
    total: number;
    limit: number;
    skip: number;
    hasMore: boolean;
  };
}

export interface GetAllAlertsParams {
  status?: AlertStatus;
  limit?: number;
  skip?: number;
  sortBy?: "createdAt" | "decidedAt";
  sortOrder?: "asc" | "desc";
}

