export async function getAllAlerts(
  params?: GetAllAlertsParams
): Promise<ApiResponse<Alert[]>> {
  await new Promise((r) => setTimeout(r, 300));

  let data = [...mockAlerts];

  if (params?.status) {
    data = data.filter((a) => a.status === params.status);
  }

  if (params?.sortBy) {
    data.sort((a, b) => {
      const first = a[params.sortBy!] || "";
      const second = b[params.sortBy!] || "";

      if (params.sortOrder === "asc") {
        return String(first).localeCompare(String(second));
      }

      return String(second).localeCompare(String(first));
    });
  }

  return {
    success: true,
    count: data.length,
    data,
    pagination: {
      total: data.length,
      limit: params?.limit ?? data.length,
      skip: params?.skip ?? 0,
      hasMore: false,
    },
  };
}

export async function getActiveAlerts(): Promise<ApiResponse<Alert[]>> {
  await new Promise((r) => setTimeout(r, 200));

  return {
    success: true,
    count: mockAlerts.filter((a) => a.status === "ACTIVE").length,
    data: mockAlerts.filter((a) => a.status === "ACTIVE"),
  };
}

export async function getAlertsBySensor(
  sensorDbId: string
): Promise<ApiResponse<Alert[]>> {
  await new Promise((r) => setTimeout(r, 200));

  const alerts = mockAlerts.filter((a) => a.sensorDbId === sensorDbId);

  return {
    success: true,
    count: alerts.length,
    data: alerts,
  };
}

export async function sendDroneForAlert(
  alertId: string,
  droneId: string,
): Promise<
  ApiResponse<{
    alert: Alert;
    drone: {
      id: string;
      name: string;
      type: string;
    };
  }>
> {
  await new Promise((r) => setTimeout(r, 500));

  const alert = mockAlerts.find((a) => a.id === alertId);

  if (!alert) {
    return {
      success: false,
      error: "Alert not found",
    };
  }

  if (alert.status !== "ACTIVE") {
    return {
      success: false,
      error: "Only ACTIVE alerts can dispatch a drone",
    };
  }

  alert.status = "SENT";
  alert.decidedAt = new Date().toISOString();
  alert.decision = `send_drone:${droneId}`;

  return {
    success: true,
    data: {
      alert,
      drone: {
        id: droneId,
        name: `Drone ${droneId}`,
        type: "Quadcopter",
      },
    },
    message: "Drone dispatched successfully",
  };
}

export async function neutraliseAlert(
  alertId: string,
  reason?: string,
): Promise<ApiResponse<Alert>> {
  await new Promise((r) => setTimeout(r, 400));

  const alert = mockAlerts.find((a) => a.id === alertId);

  if (!alert) {
    return {
      success: false,
      error: "Alert not found",
    };
  }

  if (alert.status !== "ACTIVE") {
    return {
      success: false,
      error: "Alert is already resolved",
    };
  }

  alert.status = "NEUTRALISED";
  alert.decidedAt = new Date().toISOString();
  alert.decision = reason
    ? `neutralised:${reason}`
    : "neutralised";

  return {
    success: true,
    data: alert,
    message: "Alert neutralised successfully",
  };
}
export async function getAlertById(
  alertId: string,
): Promise<ApiResponse<Alert>> {
  await new Promise((r) => setTimeout(r, 200));

  const alert = mockAlerts.find((a) => a.id === alertId);

  if (!alert) {
    return {
      success: false,
      error: "Alert not found",
    };
  }

  return {
    success: true,
    data: alert,
  };
}

export async function deleteAlert(
  alertId: string,
): Promise<ApiResponse<{ id: string }>> {
  await new Promise((r) => setTimeout(r, 300));

  const index = mockAlerts.findIndex((a) => a.id === alertId);

  if (index === -1) {
    return {
      success: false,
      error: "Alert not found",
    };
  }

  mockAlerts.splice(index, 1);

  return {
    success: true,
    data: {
      id: alertId,
    },
    message: "Alert deleted successfully",
  };
}

export async function neutraliseAllActiveAlerts(
  reason?: string,
): Promise<ApiResponse<null>> {
  await new Promise((r) => setTimeout(r, 500));

  let count = 0;

  mockAlerts.forEach((alert) => {
    if (alert.status === "ACTIVE") {
      alert.status = "NEUTRALISED";
      alert.decidedAt = new Date().toISOString();
      alert.decision = reason
        ? `neutralised:${reason}`
        : "neutralised";

      count++;
    }
  });

  return {
    success: true,
    message: `${count} alert(s) neutralised successfully`,
  };
}